'use strict';
modules.push(['plans','◈','Planos & operação']);
const businessRender=render,businessValidate=validateWorkspaceData;
function commercialDefaults(){return{activeClients:0,price:0,fixedCost:0,clientCost:0,fees:0,packages:[{name:'Essencial',audience:'Profissional individual',price:null,projects:null,storage:null},{name:'Profissional',audience:'Produção recorrente',price:null,projects:null,storage:null},{name:'Estúdio',audience:'Equipe e operação com a própria marca',price:null,projects:null,storage:null}]}}
render=()=>{businessRender();if($('.badge'))$('.badge').textContent='PROTÓTIPO FUNCIONAL · V0.3'};
function commercialPage(){state.commercial??=commercialDefaults();const c=state.commercial;$('#main').innerHTML=title('PRODUTO · PLANOS & OPERAÇÃO','Uma operação que pode crescer.','Estruture os pacotes e confira os custos antes de definir a oferta.')+notice('Planejamento comercial local. Assinaturas, cobrança, permissões, cotas no servidor e emissão fiscal ainda não estão integradas. Nenhum botão desta página contrata ou cobra valores.')+`<section class="panel"><h2>Pacotes em estudo</h2><p>Estes três segmentos são uma proposta de organização. Preencha seus próprios valores e limites. Um campo vazio significa “a definir”.</p><form id="commercial-packages"><div class="grid">${c.packages.map((p,i)=>`<article class="card"><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.audience)}</p><label>Nome do pacote<input data-package="${i}" data-key="name" value="${escapeHTML(p.name)}" maxlength="60" required></label><label>Mensalidade · R$<input data-package="${i}" data-key="price" value="${p.price??''}" type="number" min="0" step="0.01" placeholder="A definir"></label><label>Projetos ativos<input data-package="${i}" data-key="projects" value="${p.projects??''}" type="number" min="1" step="1" placeholder="A definir"></label><label>Armazenamento · GB<input data-package="${i}" data-key="storage" value="${p.storage??''}" type="number" min="1" step="1" placeholder="A definir"></label></article>`).join('')}</div><br><button class="dark">Salvar proposta de pacotes</button></form></section><section class="panel"><h2>Simulação de operação mensal</h2><p>Informe custos e valores reais da sua operação. Taxas percentuais são uma estimativa fornecida por você.</p><form id="commercial-calculator" class="formgrid">${field('Clientes pagantes','business-clients',c.activeClients,'number','min="0" step="1"')}${field('Receita mensal por cliente · R$','business-price',c.price,'number','min="0" step="0.01"')}${field('Custo fixo mensal · R$','business-fixed',c.fixedCost,'number','min="0" step="0.01"')}${field('Custo mensal por cliente · R$','business-variable',c.clientCost,'number','min="0" step="0.01"')}${field('Taxas sobre a receita · %','business-fees',c.fees,'number','min="0" max="100" step="0.1"')}<div class="full"><button class="dark">Salvar simulação</button></div></form><div id="business-result" class="metrics" style="margin-top:20px"></div></section><section class="panel"><h2>O que precisa existir para cobrar pelo uso</h2><div class="table-wrap"><table><thead><tr><th>Parte da operação</th><th>Critério de entrega</th></tr></thead><tbody>${[['Acesso por conta e equipe','Validar proprietário, administradores e editores no servidor; isolar os dados de cada cliente.'],['Planos e cotas','Conferir projetos, armazenamento, exportações e hospedagem no servidor. Não depender de verificações no navegador.'],['Pagamento','Checkout de um provedor, eventos de pagamento autenticados, operações idempotentes e estados de assinatura rastreáveis.'],['Uso e custos','Medir bytes armazenados, tráfego, processamento e retenção de backups por conta.'],['Cancelamento e recuperação','Definir período de acesso, exportação dos dados, retenção e recuperação antes de ativar cobrança.'],['Marca e publicação','Distinguir marca da produtora, cliente do tour e eventual conta revendedora. Definir domínio e hospedagem por pacote.']].map(row=>`<tr><td>${row[0]}</td><td>${row[1]}</td></tr>`).join('')}</tbody></table></div></section>`;
 const result=()=>{const n=+$('#business-clients').value,price=+$('#business-price').value,fixed=+$('#business-fixed').value,variable=+$('#business-variable').value,fees=+$('#business-fees').value;if([n,price,fixed,variable,fees].some(x=>!Number.isFinite(x)||x<0)||fees>100)return;const revenue=n*price,cost=fixed+n*variable+revenue*fees/100,contribution=price*(1-fees/100)-variable,breakEven=contribution>0?Math.ceil(fixed/contribution):null;$('#business-result').innerHTML=[[money(revenue),'Receita estimada'],[money(cost),'Custos e taxas informados'],[money(revenue-cost),'Saldo estimado'],[breakEven===null?'—':String(breakEven),'Clientes para equilíbrio']].map(([value,label])=>`<div class="metric"><div><strong style="font-size:23px">${value}</strong><small>${label}</small></div></div>`).join('')};$('#commercial-calculator').oninput=result;result();
 bind('commercial-packages','submit',async e=>{e.preventDefault();const packages=c.packages.map(p=>({...p}));for(const input of $$('[data-package]')){const value=input.dataset.key==='name'?input.value.trim():input.value===''?null:Number(input.value);packages[+input.dataset.package][input.dataset.key]=value}if(packages.some(p=>!p.name))return;c.packages=packages;await save();toast('Proposta de pacotes salva. Não há cobrança ativa.');});
 bind('commercial-calculator','submit',async e=>{e.preventDefault();Object.assign(c,{activeClients:+$('#business-clients').value,price:+$('#business-price').value,fixedCost:+$('#business-fixed').value,clientCost:+$('#business-variable').value,fees:+$('#business-fees').value});await save();toast('Simulação salva neste navegador.');});
}
validateWorkspaceData=data=>{businessValidate(data);const c=data.commercial;if(c){for(const key of['activeClients','price','fixedCost','clientCost','fees'])if(typeof c[key]!=='number'||!Number.isFinite(c[key])||c[key]<0)throw Error('Simulação comercial inválida.');if(c.fees>100||!Array.isArray(c.packages)||c.packages.length!==3)throw Error('Pacotes inválidos.');for(const p of c.packages){if(typeof p.name!=='string'||p.name.length>60||typeof p.audience!=='string')throw Error('Identificação de pacote inválida.');for(const key of['price','projects','storage'])if(p[key]!==null&&(typeof p[key]!=='number'||!Number.isFinite(p[key])||p[key]<0))throw Error('Limite de pacote inválido.');}}return data};
